      // "summarized" claim.
      cli.io.writeln(
        '[context trimmed] ${pass.tokensBefore} → ${pass.tokensAfter} '
        'tokens (summarizer unavailable — kept the most recent messages '
        'locally; the session file keeps the full history)',
