blocks.text:
/// CLI user preferences: last model, provider, base URL, mode, approval
/// policy, prompt overrides, and (optionally) model roles with fallback
/// chains.
///
/// Stored in `~/.fah/config.yaml` so the terminal REPL remembers choices
/// between runs.
library;

import 'dart:convert';
import 'dart:io';

