    throw ConfigException('"tui.statusLine" must be a map, got: $statusLine');
  }
  return TuiSectionConfig(
    theme: theme,
    classic: classic,
    statusLine: statusLine == null ? null : parseStatusLineConfig(statusLine),
  );
}

