/// Strict-section validators keyed by the top-level key, shared by
/// `check` and `set` (the "never persist what the next boot would
/// reject" guarantee). The a2a token env resolves at boot; structural
/// validation keeps `${NAME}` tokens literal — the permissive resolver
/// hands back the raw token, so an unset variable is a boot problem,
/// not a schema error.
final _sectionValidators = <String, void Function(dynamic value, String label)>{
  'memory': (value, _) => MemoryConfig.fromYaml(value),
  'cube': (value, _) => CubeSettings.fromYaml(value),
  'mcp': (value, _) => McpConfig.fromYaml(value),
  'redact': (value, _) => validateRedactSection(value),
  // The spills section (issue #678) parses tolerantly by design —
  // unknown keys and mistyped scalars become notes on the config, never
  // schema errors — so the validator never throws.
  'spills': (value, _) => SpillsConfig.fromYaml(value),
  'tools': (value, _) => ToolsConfig.fromYaml(value),
  // The links section (issue #691): strict on shape (a bad value throws,
  // nothing persists), tolerant on unknown keys (notes, never errors).
  'links': (value, _) => LinksConfig.fromYaml(value),
  'compaction': (value, label) =>
      CompactionEngine.fromSection(value, label: label),
  'models': (value, _) => ModelsConfig.fromYaml(value),
  'customProviders': (value, _) => _validateCustomProviders(value),
  'ttsr': (value, label) => TtsrConfig.fromYaml(value, sourcePath: label),
  'images': (value, _) => _validateImagesSection(value),
  'a2a': (value, _) => A2aConfig.fromYaml(value, (name) => '\${$name}'),
  'fabric': (value, _) => FabricConfig.fromYaml(value),
  'providerTimeouts': (value, _) => validateProviderTimeoutsSection(value),
  'agent': (value, _) => validateAgentSection(value),
  'skills': (value, _) => _validateSkillsSection(value),
  // The power section (sleep prevention, issue #325) delegates to the
  // SAME public strict parser CliConfig.fromYaml uses — no mirror to
  // keep in sync, unlike the private-parser sections above.
  'power': (value, _) => parsePowerSection(value),
  // The subagents section (background-subagent heartbeat, issue #383)
  // delegates to the SAME public strict parser CliConfig.fromYaml uses —
  // no mirror to keep in sync.
  'subagents': (value, _) => SubagentsConfig.fromYaml(value),
  // Deep validation (strict prompt names) lives behind cli_config.dart's
  // strict parser; here the section must be a string-valued map.
  'prompts': (value, _) => _validateStringMap(value, 'prompts'),
  // Issue #279: `tui.theme` must be a non-empty string (the theme itself
  // resolves at boot, where the user-theme set is known; unknown names
  // warn and keep the default).
  'tui': (value, label) => _validateTuiSection(value, label),
  // The output section (gh-1198) delegates to the SAME pure strict
  // parser CliConfig.fromYaml uses — no mirror to keep in sync.
  'output': (value, _) => parseOutputSection(value),
  // The self-update policy (issue #1377) mirrors cli_config.dart's strict
  // scalar parser (no import — dart:io); pinned to it by unit test.
  'auto_update': (value, _) => validateAutoUpdateScalar(value),
};

/// The `auto_update` scalar validator (issue #1377): `true`, `false` or
/// the `"notify"` string are legal; anything else throws — the same rule
/// `CliConfig.fromYaml` applies at boot (`autoUpdateModeFromYaml`, which
/// this file cannot import — it uses `dart:io`). Pinned to it by unit
/// test (the `pins against cli_config.dart` group).
void validateAutoUpdateScalar(Object? value) {
  // The yaml package hands back plain scalars (older versions wrap them
  // in YamlScalar) — accept both, like the `_scalarKeys` branch above.
  final scalar = value is YamlScalar ? value.value : value;
  if (scalar is bool || scalar == 'notify' || scalar == null) return;
  throw ConfigException(
    '"auto_update" must be true, false, or "notify", got: $scalar',
  );
}

void _validateTuiSection(Object? node, String label) {
  if (node is! YamlMap) {
    throw ConfigException('$label: tui section must be a map');
  }
  final unknown = [
    for (final key in node.keys)
      if (!{'theme'}.contains('$key')) '$key',
  ];
  if (unknown.isNotEmpty) {
    throw ConfigException(
      '$label: unknown tui key(s): ${unknown.join(', ')} (known: theme)',
    );
  }
  final theme = node['theme'];
  if (theme == null || '$theme'.trim().isEmpty) {
    throw ConfigException('$label: tui.theme must be a non-empty theme name');
  }
}

void _validateCustomProviders(Object? node) {
  if (node is! YamlList) {
    throw ConfigException('must be a list of provider entries');
  }
  for (final entry in node) {
    CustomProviderEntry.fromYaml(entry);
  }
}

/// The strict `providerTimeouts:` section validator (mirrors the public
/// parser `parseProviderTimeouts` in `cli_config.dart`; pinned by test).
/// Shared by `check`, `set` and the settings flow (issue #393).
void validateProviderTimeoutsSection(Object? node) {
  if (node is! YamlMap) {
    throw ConfigException('must be a map, got: $node');
  }
  for (final entry in node.entries) {
    final key = '${entry.key}';
    if (key != 'connectTimeoutMs' && key != 'streamIdleTimeoutMs') {
      throw ConfigException('unknown "providerTimeouts" key: $key');
    }
    final value = entry.value;
    if (value is! int || value <= 0) {
      throw ConfigException(
        '"providerTimeouts.$key" must be a positive integer (milliseconds)',
      );
    }
  }
}

/// The strict `agent:` section validator, shared by `check`, `set` and
/// the settings flow (issues #394/#680). Mirrors the private boot parser
/// in `cli_config.dart` (pinned by test): the section takes exactly
/// `contextWindowCap` (a positive integer at or above the compaction
/// reserve — a cap below 16384 must never soften that floor; a cap above
/// the catalog window is the #729 raise path and validates unchanged),
/// `mode` (the load preset `default|pi|omp`, validated by the shared
/// [agentLoadModeValidationError] rule), `misuseBreaker` (a boolean —
/// gh-1572 makes the emitter render the kill switch, so the mirror has
/// to accept it or `fa config check` false-fails on fa's own output) and
/// `stuckTool` (validated with the section's own strict parser, the same
/// one the boot parser applies).
///
/// The per-key checks live in [_agentKeyValidators] — the same
/// table-driven shape the section dispatch above uses — so the dispatch
/// function itself stays flat (the gh-1572 rework's two new keys pushed
/// the switch form over the repo's CRAP ratchet; the table cannot drift
/// the same way a switch can).
void validateAgentSection(Object? node) {
  if (node is! YamlMap) {
    throw ConfigException('must be a map, got: $node');
  }
  for (final entry in node.entries) {
    final validate = _agentKeyValidators['${entry.key}'];
    if (validate == null) {
      throw ConfigException('unknown "agent" key: ${entry.key}');
    }
    validate(entry.value);
  }
}

