  group('formatCompactionReport (UT-report)', () {
    test('renders exact numbers, the engine, and the record counts', () {
      final pass = AutoCompactorPass(
        pass: 1,
        tokensBefore: 210925,
        tokensAfter: 45123,
        fallback: 'smol',
        ok: true,
        summary: '## Decisions\n- ship it',
        hiddenRecords: 42,
        summarizedMessages: 17,
