    });
    test('a summarizer pass keeps the hidden/summarized-only line', () {
      final pass = AutoCompactorPass(
        pass: 1,
        tokensBefore: 1000,
        tokensAfter: 100,
        fallback: 'smol',
        ok: true,
        summary: 's',
        hiddenRecords: 4,
        summarizedMessages: 2,
      );
      expect(
        formatCompactionReport(pass, auto: false)[2],
        'records: 4 hidden · 2 summarized',
      );
    });
