void _checkStrictKeys(YamlMap node, String path, Set<String> knownKeys) {
  for (final key in node.keys) {
    if (!knownKeys.contains('$key')) {
      throw ConfigException(
        'unknown "$path" key: $key (known: ${knownKeys.join(', ')})',
      );
    }
  }
}

