}

/// Validates the `classic:` kill switch; false when unset.
bool _tuiClassicFlag(Object? classic) {
  if (classic != null && classic is! bool) {
    throw ConfigException('"tui.classic" must be a boolean');
  }
  return classic as bool? ?? false;
