    const {'theme', 'classic', 'showCompactionDetails', 'statusLine'},
  );
  final theme = _tuiThemeName(node['theme']);
  final classic = _tuiClassicFlag(node['classic']);
  final showCompactionDetails = _tuiShowCompactionDetailsFlag(
