group('pins against cli_config.dart', () {
  test('the output section validates identically (gh-1198)', () {
    final bad = loadYaml('output:\n  bogus: 1\n') as YamlMap;
    expect(() => CliConfig.fromYaml(bad), throwsConfigException);
    final good = loadYaml('output:\n  streamThinking: true\n') as YamlMap;
    expect(() => CliConfig.fromYaml(good), returnsNormally);
    expect(CliConfig.fromYaml(good).streamThinking, isTrue);
  });

  test('the top-level key set matches what the CLI config reads', () {
    final bodies = [
      'lib/src/cli/cli_config.dart',
      'lib/src/model_roles/roles_config.dart',
      // The provider-queue resolver reads its section from both config
      // files at boot (issue #418).
      'lib/src/cli/startup.dart',
    ].map(File.new).map((file) => file.readAsStringSync());
    for (final key in configTopLevelKeys) {
      final found = bodies.any((body) => body.contains("'$key'"));
      expect(
        found,
        isTrue,
        reason: 'config key "$key" is not read by the CLI config parsers',
      );
    }
  });

  test('providerTimeouts validation agrees with CliConfig.fromYaml', () {
    final bad = loadYaml('providerTimeouts:\n  bogus: 1\n') as YamlMap;
    expect(() => CliConfig.fromYaml(bad), throwsConfigException);
    final good =
        loadYaml('providerTimeouts:\n  connectTimeoutMs: 1000\n') as YamlMap;
    expect(() => CliConfig.fromYaml(good), returnsNormally);
  });

  test('skills validation agrees with CliConfig.fromYaml', () {
    final bad = loadYaml('skills:\n  access: sometimes\n') as YamlMap;
    expect(() => CliConfig.fromYaml(bad), throwsConfigException);
    final good = loadYaml('skills:\n  access: ask\n') as YamlMap;
    expect(() => CliConfig.fromYaml(good), returnsNormally);
  });

  test('power validation agrees with CliConfig.fromYaml (issue #325)', () {
    final bad = loadYaml('power:\n  sleepPrevention: nap\n') as YamlMap;
    expect(() => CliConfig.fromYaml(bad), throwsConfigException);
    final good = loadYaml('power:\n  sleepPrevention: system\n') as YamlMap;
    expect(
      CliConfig.fromYaml(good).powerSleepPrevention,
      PowerAssertionLevel.system,
    );
  });

  test('agent validation agrees with CliConfig.fromYaml (issue #273)', () {
    final bad = loadYaml('agent:\n  contextWindowCap: 16383\n') as YamlMap;
    expect(() => CliConfig.fromYaml(bad), throwsConfigException);
    final good = loadYaml('agent:\n  contextWindowCap: 256000\n') as YamlMap;
    expect(() => CliConfig.fromYaml(good), returnsNormally);
  });

  test('agent validation agrees on the #729 raise path too', () {
    // A cap above the catalog window is the raise override: both the
    // shared validator and the boot parser accept it identically.
    final raised =
        loadYaml('agent:\n  contextWindowCap: 1000000\n') as YamlMap;
    final agentNode = raised['agent'] as YamlMap;
    expect(() => validateAgentSection(agentNode), returnsNormally);
    expect(() => CliConfig.fromYaml(raised), returnsNormally);
    expect(CliConfig.fromYaml(raised).contextWindowCap, 1000000);
  });

  test('agent validation agrees on the misuseBreaker kill switch '
      '(gh-1572)', () {
    // gh-1572 makes the emitter render `agent.misuseBreaker: false`;
    // the strict mirror must accept exactly what the boot parser
    // accepts, or `fa config check` false-fails on fa's own output and
    // the settings-hub agent upserts refuse to save.
    final bad = loadYaml('agent:\n  misuseBreaker: off\n') as YamlMap;
    expect(() => CliConfig.fromYaml(bad), throwsConfigException);
    expect(() => validateAgentSection(bad['agent']), throwsConfigException);
    final good = loadYaml('agent:\n  misuseBreaker: false\n') as YamlMap;
    final agentNode = good['agent'] as YamlMap;
    expect(() => validateAgentSection(agentNode), returnsNormally);
    expect(() => CliConfig.fromYaml(good), returnsNormally);
