/// Throws the first collected error as a failure with its message, so tests
/// can assert on named diagnostics.
Future<ConfigCheckReport> checkOrThrow(ConfigService service) async {
  final report = await service.check();
  expect(
    report.ok,
    isTrue,
    reason:
