/// The config service core (issue #29 S3): check/get/set/paths over the
/// user + project config pair on a [MemoryExecutionEnv], plus the pins that
/// keep the service's mirrored strict validators and top-level key set
/// honest against `cli_config.dart` (which the pure core cannot import).
library;

import 'dart:io';

import 'package:flutter_agent_harness/src/cli/cli_config.dart';
import 'package:flutter_agent_harness/src/agent/stuck_tool.dart';
import 'package:flutter_agent_harness/src/config/config_service.dart';
import 'package:flutter_agent_harness/src/env/memory_execution_env.dart';
import 'package:flutter_agent_harness/src/power_config.dart';
import 'package:flutter_agent_harness/src/exceptions.dart';
import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

const _globalConfig = '/home/.fah/config.yaml';
const _projectConfig = '/work/.fah/config.yaml';

const _validGlobal = '''
provider: openai-completions
model: openai/gpt-4o-mini
baseUrl: https://openrouter.ai/api/v1
mode: code
approvalMode: yolo
''';

const _validProject = '''
memory:
  projectPath: ./memory
tools:
  web_search: false
''';

const _commentedProject = '''
# my project config
memory:
  projectPath: ./old # committed with the repo
tools:
  web_search: false
''';

Matcher get throwsConfigException => throwsA(isA<ConfigException>());

/// Throws the first collected error as a failure with its message, so tests
/// can assert on named diagnostics.
Future<ConfigCheckReport> checkOrThrow(ConfigService service) async {
  final report = await service.check();
  expect(
    report.ok,
    isTrue,
    reason:
        'unexpected errors: '
        '${report.errors.map((e) => e.toString()).join('; ')}',
  );
  return report;
}

void main() {
  late MemoryExecutionEnv env;
  late ConfigService service;

  setUp(() {
    env = MemoryExecutionEnv(cwd: '/work');
    service = ConfigService(env: env, homeDir: '/home');
  });

  Future<String> read(String path) async {
    final result = await env.readTextFile(path);
    return result.valueOrNull ?? '';
  }

  group('check', () {

{"newText":"  group('pins against cli_config.dart', () {
    test('tui validation agrees with CliConfig.fromYaml (gh-1636)', () {
      // The gh-1636 opt-in must be writable through `fa config set` AND
      // boot-parse identically — the two mirrors accept exactly the same
      // shapes.
      final bad = loadYaml('tui:\n  showCompactionDetails: sure\n')
          as YamlMap;
      expect(() => CliConfig.fromYaml(bad), throwsConfigException);
      final good =
          loadYaml('tui:\n  showCompactionDetails: true\n') as YamlMap;
      expect(() => CliConfig.fromYaml(good), returnsNormally);
      expect(CliConfig.fromYaml(good).tuiShowCompactionDetails, isTrue);
      // The emitter never renders the default, so the mirror's tolerance
      // of a theme-less section is what `fa config set` needs.
      final setShape = CliConfig(tuiShowCompactionDetails: true).toYaml();
      expect(setShape, contains('showCompactionDetails: true'));
      expect(() => CliConfig.fromYaml(loadYaml(setShape) as YamlMap),
          returnsNormally);
    });

    test('the output section validates identically (gh-1198)', () {","oldText":"  group('pins against cli_config.dart', () {
    test('the output section validates identically (gh-1198)', () {","path":"test/config/config_service_test.dart"}

